/**
 * kon-agile
 *
 * Sistema de gestión ágil con aprobación humana para sugerencias de IA
 */
export interface AgileApi {
  /**
   * Add or change a project member
   *
   * Adds a user to the project with a role, or changes the role if already a member (repeating it leaves the same state). Only the project owner (or admin); a member or viewer gets 403, a non-member 404.
   *
   * REST: `POST /api/agile/projects/{id}/members` · scope `kon:agile:anadir-miembro-a-proyecto`
   * idempotent (safe to retry)
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly anadirMiembroAProyecto: Operation<AnadirMiembroAProyectoParams, AnadirMiembroAProyectoResponse>;
  /**
   * Approve an intake into an issue
   *
   * Turns a pending intake into an issue of its project (the optional body may override name, type, priority, state, cycle, module, assignee…) and marks the intake accepted, signed by the caller. Owner or member of the project (viewer: 403; non-member: 404); an intake already decided is a 409.
   *
   * REST: `POST /api/agile/intakes/{intakeId}/approve` · scope `kon:agile:aprobar-intake`
   * not idempotent (an Idempotency-Key is sent automatically)
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly aprobarIntake: Operation<AprobarIntakeParams, AprobarIntakeResponse>;
  /**
   * Approve an intake (DataExplorer alias)
   *
   * Same as POST /intakes/:intakeId/approve, under the table name the admin DataExplorer uses for its row actions.
   *
   * REST: `POST /api/agile/agile_intakes/{id}/approve` · scope `kon:agile:aprobar-intake-de-tabla`
   * not idempotent (an Idempotency-Key is sent automatically)
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly aprobarIntakeDeTabla: Operation<AprobarIntakeDeTablaParams, AprobarIntakeDeTablaResponse>;
  /**
   * Comment on an issue
   *
   * Adds a comment (signed with the caller's id) and updates the issue's comment count. Owner or member of its project (viewer: 403; non-member: 404). A `parentId` must be a comment of the same issue (422).
   *
   * REST: `POST /api/agile/issues/{key}/comments` · scope `kon:agile:comentar-issue`
   * not idempotent (an Idempotency-Key is sent automatically)
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly comentarIssue: Operation<ComentarIssueParams, ComentarIssueResponse>;
  /**
   * Convert an intake into an issue (DataExplorer alias)
   *
   * Same as POST /intakes/:intakeId/approve (the DataExplorer's convert row action).
   *
   * REST: `POST /api/agile/agile_intakes/{id}/convert` · scope `kon:agile:convertir-intake-de-tabla`
   * not idempotent (an Idempotency-Key is sent automatically)
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly convertirIntakeDeTabla: Operation<ConvertirIntakeDeTablaParams, ConvertirIntakeDeTablaResponse>;
  /**
   * Create a sprint
   *
   * Creates a cycle (sprint) in the project, signed by the caller. Owner or member (viewer: 403; non-member: 404). `endDate` before `startDate` is a 422.
   *
   * REST: `POST /api/agile/{projectId}/cycles` · scope `kon:agile:crear-ciclo`
   * not idempotent (an Idempotency-Key is sent automatically)
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly crearCiclo: Operation<CrearCicloParams, CrearCicloResponse>;
  /**
   * Create an issue
   *
   * Creates an issue with the next key of the project (e.g. PLAT-13), in the given state or the default one, signed by the caller. Owner or member of the project (viewer: 403; non-member: 404). State, cycle, module and parent must belong to the project and the assignee must be a member (422); a project with no default state is a 409.
   *
   * REST: `POST /api/agile/{projectId}/issues` · scope `kon:agile:crear-issue`
   * not idempotent (an Idempotency-Key is sent automatically)
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly crearIssue: Operation<CrearIssueParams, CrearIssueResponse>;
  /**
   * Create an epic
   *
   * Creates a module (epic) in the project, signed by the caller. Owner or member (viewer: 403; non-member: 404).
   *
   * REST: `POST /api/agile/{projectId}/modules` · scope `kon:agile:crear-modulo`
   * not idempotent (an Idempotency-Key is sent automatically)
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly crearModulo: Operation<CrearModuloParams, CrearModuloResponse>;
  /**
   * Create an agile project
   *
   * Creates a project with five default states (Backlog, Todo, In Progress, Done, Cancelled); the caller becomes its owner. Only the team (admin or editor) may create projects: any other account gets 403 once its body is valid. The identifier is stored upper-case and must be unique (409).
   *
   * REST: `POST /api/agile/projects` · scope `kon:agile:crear-proyecto`
   * not idempotent (an Idempotency-Key is sent automatically)
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly crearProyecto: Operation<CrearProyectoParams, CrearProyectoResponse>;
  /**
   * Update an issue
   *
   * Changes the given fields of an issue. Owner or member of its project (viewer: 403; non-member: 404). State, cycle, module and parent must belong to the same project, and the assignee must be a member (422).
   *
   * REST: `PATCH /api/agile/issues/{key}` · scope `kon:agile:editar-issue`
   * not idempotent (an Idempotency-Key is sent automatically)
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly editarIssue: Operation<EditarIssueParams, EditarIssueResponse>;
  /**
   * Read a project's Kanban board
   *
   * READ-ONLY. The board of one agile project: its states (name, color, group) with the issues in each, newest first, and counts per state group. Only for members of the project (owner, member or viewer); anyone else gets 404. It never changes anything: to propose work use agile_submit_intake.
   *
   * REST: `GET /api/agile/projects/{projectId}/board` · scope `kon:agile:leer-tablero`
   * idempotent (safe to retry) · MCP tool `agile_read_board`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly leerTablero: Operation<LeerTableroParams, LeerTableroResponse>;
  /**
   * List a project's sprints
   *
   * The cycles (sprints) of a project, latest start first. Only for members (and admin); anyone else gets 404.
   *
   * REST: `GET /api/agile/{projectId}/cycles` · scope `kon:agile:listar-ciclos`
   * idempotent (safe to retry)
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listarCiclos: Operation<ListarCiclosParams, ListarCiclosResponse>;
  /**
   * List an issue's comments
   *
   * The comments of an issue, oldest first. Only for members of its project (and admin); anyone else gets 404.
   *
   * REST: `GET /api/agile/issues/{key}/comments` · scope `kon:agile:listar-comentarios-de-issue`
   * idempotent (safe to retry)
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listarComentariosDeIssue: Operation<ListarComentariosDeIssueParams, ListarComentariosDeIssueResponse>;
  /**
   * List a project's triage inbox
   *
   * The intakes of a project, newest first; `status` (pending, accepted, declined, duplicate…) filters. Only for members (and admin); anyone else gets 404.
   *
   * REST: `GET /api/agile/{projectId}/intakes` · scope `kon:agile:listar-intakes`
   * idempotent (safe to retry)
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listarIntakes: Operation<ListarIntakesParams, ListarIntakesResponse>;
  /**
   * List a project's issues
   *
   * Issues of a project, oldest first, with their state. Filters: `stateId`, `cycleId`, `moduleId` (uuids, else 400), `assigneeId`, `type`, `priority`, `search` (name contains) and `limit` (1-200, default 50). Only for members (and admin); anyone else gets 404.
   *
   * REST: `GET /api/agile/{projectId}/issues` · scope `kon:agile:listar-issues`
   * idempotent (safe to retry)
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listarIssues: Operation<ListarIssuesParams, ListarIssuesResponse>;
  /**
   * List a project's members
   *
   * User id and role (owner, member, viewer) of each member, oldest first. Only for members of the project (and admin); anyone else gets 404.
   *
   * REST: `GET /api/agile/projects/{id}/members` · scope `kon:agile:listar-miembros-de-proyecto`
   * idempotent (safe to retry)
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listarMiembrosDeProyecto: Operation<ListarMiembrosDeProyectoParams, ListarMiembrosDeProyectoResponse>;
  /**
   * List a project's epics
   *
   * The modules (epics) of a project, by name. Only for members (and admin); anyone else gets 404.
   *
   * REST: `GET /api/agile/{projectId}/modules` · scope `kon:agile:listar-modulos`
   * idempotent (safe to retry)
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listarModulos: Operation<ListarModulosParams, ListarModulosResponse>;
  /**
   * List my agile projects
   *
   * The projects the caller is a member of (owner, member or viewer; admin: all), by name, with cover image URLs. `isArchived=true|false` filters. An agent key needs `usuario:actuar` or an agile scope to act as an account here.
   *
   * REST: `GET /api/agile/projects` · scope `kon:agile:listar-proyectos`
   * idempotent (safe to retry)
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listarProyectos: Operation<ListarProyectosParams, ListarProyectosResponse>;
  /**
   * Mark an intake as a duplicate
   *
   * Marks a pending intake as a duplicate of an issue of the SAME project (`duplicateOfId`, else 422), signed by the caller. Owner or member of the project (viewer: 403; non-member: 404); an intake already decided is a 409.
   *
   * REST: `POST /api/agile/intakes/{intakeId}/duplicate` · scope `kon:agile:marcar-intake-duplicado`
   * not idempotent (an Idempotency-Key is sent automatically)
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly marcarIntakeDuplicado: Operation<MarcarIntakeDuplicadoParams, MarcarIntakeDuplicadoResponse>;
  /**
   * Propose work to a project's triage inbox
   *
   * Creates an intake (status 'pending') in the project's triage inbox. It does NOT create an issue: a human owner or member approves or declines it, and only then does an issue appear on the board. Any member of the project can propose, viewers included; anyone else gets 404. The intake is signed with the caller's id.
   *
   * REST: `POST /api/agile/{projectId}/intakes` · scope `kon:agile:proponer-intake`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `agile_submit_intake`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly proponerIntake: Operation<ProponerIntakeParams, ProponerIntakeResponse>;
  /**
   * Remove a project member
   *
   * Removes a user from the project. Only the project owner (or admin). The user who created the project cannot be removed (409); a user who is not a member is a 404.
   *
   * REST: `DELETE /api/agile/projects/{id}/members/{userId}` · scope `kon:agile:quitar-miembro-de-proyecto`
   * idempotent (safe to retry) · sensitive: may come back as a proposal pending human approval
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly quitarMiembroDeProyecto: Operation<QuitarMiembroDeProyectoParams, QuitarMiembroDeProyectoResponse>;
  /**
   * Decline an intake
   *
   * Marks a pending intake as declined, with an optional reason, signed by the caller. Owner or member of the project (viewer: 403; non-member: 404); an intake already decided is a 409. The body is optional.
   *
   * REST: `POST /api/agile/intakes/{intakeId}/decline` · scope `kon:agile:rechazar-intake`
   * not idempotent (an Idempotency-Key is sent automatically)
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly rechazarIntake: Operation<RechazarIntakeParams, RechazarIntakeResponse>;
  /**
   * Decline an intake (DataExplorer alias)
   *
   * Same as POST /intakes/:intakeId/decline, under the table name the admin DataExplorer uses for its row actions.
   *
   * REST: `POST /api/agile/agile_intakes/{id}/decline` · scope `kon:agile:rechazar-intake-de-tabla`
   * not idempotent (an Idempotency-Key is sent automatically)
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly rechazarIntakeDeTabla: Operation<RechazarIntakeDeTablaParams, RechazarIntakeDeTablaResponse>;
  /**
   * Read an issue by its key
   *
   * One issue by its key (e.g. PLAT-12), without its internal `props`. Only for members of its project (and admin); anyone else gets 404.
   *
   * REST: `GET /api/agile/issues/{key}` · scope `kon:agile:ver-issue`
   * idempotent (safe to retry)
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly verIssue: Operation<VerIssueParams, VerIssueResponse>;
  /**
   * Read an agile project
   *
   * One project with its states (by sequence) and cover image URLs. Only for its members (and admin); anyone else gets 404.
   *
   * REST: `GET /api/agile/projects/{id}` · scope `kon:agile:ver-proyecto`
   * idempotent (safe to retry)
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly verProyecto: Operation<VerProyectoParams, VerProyectoResponse>;
}
